    }

    @Test
    void corporatePlanRequiresValidCompanyCode() throws Exception {
        String corporateWithValidCode = """
                {"roomNumber": 201, "guestName": "Carla Dias", "guestEmail": "carla@example.com",
                 "guestCpf": "111.222.333-44", "checkIn": "2027-03-10", "checkOut": "2027-03-12",
                 "guests": 2, "ratePlan": "CORPORATE", "companyCode": "TECNOSUL"}
                """;
        HttpResponse<String> created = post("/reservations", corporateWithValidCode);
        assertEquals(201, created.statusCode());
        JsonNode reservation = json.readTree(created.body());
        assertEquals(686.22, reservation.get("total").asDouble());
        assertEquals(93.58, reservation.get("discount").asDouble());

        String corporateWithInvalidCode = """
                {"roomNumber": 201, "guestName": "Carla Dias", "guestEmail": "carla@example.com",
                 "guestCpf": "111.222.333-44", "checkIn": "2027-03-13", "checkOut": "2027-03-15",
                 "guests": 2, "ratePlan": "CORPORATE", "companyCode": "UNKNOWN"}
                """;
        HttpResponse<String> invalid = post("/reservations", corporateWithInvalidCode);
        assertEquals(400, invalid.statusCode());
        assertEquals("INVALID_REQUEST", json.readTree(invalid.body()).get("error").asText());
    }

    @Test
    void weekendPackageRequiresFridayToSunday() throws Exception {
        String validWeekend = """
                {"roomNumber": 201, "guestName": "Carla Dias", "guestEmail": "carla@example.com",
                 "guestCpf": "111.222.333-44", "checkIn": "2027-03-12", "checkOut": "2027-03-14",
                 "guests": 2, "ratePlan": "WEEKEND_PACKAGE"}
                """;
        HttpResponse<String> created = post("/reservations", validWeekend);
        assertEquals(201, created.statusCode());
        JsonNode reservation = json.readTree(created.body());
        assertEquals(820.00, reservation.get("total").asDouble());
        assertEquals(0.00, reservation.get("discount").asDouble());

        String invalidWeekend = """
                {"roomNumber": 201, "guestName": "Carla Dias", "guestEmail": "carla@example.com",
                 "guestCpf": "111.222.333-44", "checkIn": "2027-03-10", "checkOut": "2027-03-12",
                 "guests": 2, "ratePlan": "WEEKEND_PACKAGE"}
                """;
        HttpResponse<String> invalid = post("/reservations", invalidWeekend);
        assertEquals(400, invalid.statusCode());
        assertEquals("INVALID_REQUEST", json.readTree(invalid.body()).get("error").asText());
    }

    @Test
    void longStayRequiresSevenOrMoreNights() throws Exception {
        String validLongStay = """
                {"roomNumber": 101, "guestName": "Carla Dias", "guestEmail": "carla@example.com",
                 "guestCpf": "111.222.333-44", "checkIn": "2027-03-01", "checkOut": "2027-03-08",
                 "guests": 2, "ratePlan": "LONG_STAY"}
                """;
        HttpResponse<String> created = post("/reservations", validLongStay);
        assertEquals(201, created.statusCode());
        JsonNode reservation = json.readTree(created.body());
        assertEquals(1574.37, reservation.get("total").asDouble());
        assertEquals(174.93, reservation.get("discount").asDouble());

        String shortStay = """
                {"roomNumber": 101, "guestName": "Carla Dias", "guestEmail": "carla@example.com",
                 "guestCpf": "111.222.333-44", "checkIn": "2027-03-01", "checkOut": "2027-03-05",
                 "guests": 2, "ratePlan": "LONG_STAY"}
                """;
        HttpResponse<String> invalid = post("/reservations", shortStay);
        assertEquals(400, invalid.statusCode());
        assertEquals("INVALID_REQUEST", json.readTree(invalid.body()).get("error").asText());
    }
}

